#include <cstdint>
#include <cstdlib>
#include <deque>
#include <iostream>

int main() {
    constexpr std::int64_t kDontExceedThisValue = 100000000;

    std::deque<int> empty_deq;
    std::int64_t counter = 0;

    while (*empty_deq.begin() < 1 && counter < kDontExceedThisValue) {
        ++counter;
    }
    std::cout << "counter = " << counter << '\n';

    return EXIT_SUCCESS;
}
